Dataspatium.assets.register("presets/api/asub-aland.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"asub-aland\",\n  \"name\": \"ÅSUB Ålands statistik\",\n  \"publisher\": \"Ålands statistik- och utredningsbyrå (ÅSUB)\",\n  \"description\": \"Ålands officiella statistik: befolkning, arbetsmarknad, ekonomi, boende, turism, miljö och mer, på svenska och engelska. Bläddra i ämnesträdet, välj tabell och värden per variabel.\",\n  \"docs\": \"https://www.asub.ax/sv/statistik\",\n  \"license\": { \"name\": \"Fri att använda med källangivelse (ÅSUB)\", \"url\": \"https://www.asub.ax/sv/statistik\" },\n  \"level\": 1,\n  \"country\": \"AX\",\n  \"baseUrl\": \"https://pxweb.asub.ax/PXWeb/api/v1/sv/Statistik\",\n  \"auth\": { \"type\": \"none\" },\n  \"rateLimit\": { \"requests\": 10, \"perSeconds\": 1 },\n  \"family\": { \"type\": \"pxweb\", \"version\": 1, \"maxCells\": 100000, \"urls\": { \"sv\": \"https://pxweb.asub.ax/PXWeb/api/v1/sv/Statistik\", \"en\": \"https://pxweb.asub.ax/PXWeb/api/v1/en/Statistik\" } },\n  \"notes\": \"Ange källa: ÅSUB.\",\n  \"i18n\": {\n    \"en\": { \"name\": \"ÅSUB Statistics Åland\", \"publisher\": \"Statistics and Research Åland (ÅSUB)\", \"description\": \"Åland's official statistics: population, labour market, economy, housing, tourism, environment and more, in Swedish and English. Browse the subject tree, pick a table and values per variable.\", \"notes\": \"Cite the source: ÅSUB.\" },\n    \"da\": { \"name\": \"ÅSUB Ålands statistik\", \"publisher\": \"Ålands statistik- och utredningsbyrå (ÅSUB)\", \"description\": \"Ålands officielle statistik: befolkning, arbejdsmarked, økonomi, boliger, turisme, miljø og mere, på svensk og engelsk. Gennemse emnetræet, vælg tabel og værdier pr. variabel.\", \"notes\": \"Angiv kilde: ÅSUB.\" },\n    \"nb\": { \"name\": \"ÅSUB Ålands statistikk\", \"publisher\": \"Ålands statistik- och utredningsbyrå (ÅSUB)\", \"description\": \"Ålands offisielle statistikk: befolkning, arbeidsmarked, økonomi, bolig, turisme, miljø og mer, på svensk og engelsk. Bla i emnetreet, velg tabell og verdier per variabel.\", \"notes\": \"Oppgi kilde: ÅSUB.\" },\n    \"fi\": { \"name\": \"ÅSUB Ahvenanmaan tilastot\", \"publisher\": \"Ahvenanmaan tilasto- ja tutkimustoimisto (ÅSUB)\", \"description\": \"Ahvenanmaan virallinen tilasto: väestö, työmarkkinat, talous, asuminen, matkailu, ympäristö ja muuta, ruotsiksi ja englanniksi. Selaa aihepuuta, valitse taulukko ja arvot muuttujittain.\", \"notes\": \"Mainitse lähde: ÅSUB.\" },\n    \"is\": { \"name\": \"ÅSUB hagtölur Álandseyja\", \"publisher\": \"Ålands statistik- och utredningsbyrå (ÅSUB)\", \"description\": \"Opinber hagtölur Álandseyja: mannfjöldi, vinnumarkaður, efnahagur, húsnæði, ferðaþjónusta, umhverfi og fleira, á sænsku og ensku. Flettu í efnistrénu, veldu töflu og gildi fyrir hverja breytu.\", \"notes\": \"Tilgreindu heimild: ÅSUB.\" }\n  }\n}\n");
